import{_ as t,o as l,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Keynote - State of Ceph","description":"","frontmatter":{"title":"Keynote - State of Ceph","date":"2026-07-09T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","分布式存储","社区动态","版本更新","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_State_of_Ceph.md","filePath":"posts/2025/Keynote_-_State_of_Ceph.md","lastUpdated":1780460162000}'),r={name:"posts/2025/Keynote_-_State_of_Ceph.md"};function n(i,e,s,h,g,p){return l(),o("div",null,[...e[0]||(e[0]=[a('<p>Ceph社区会议纪要中，Neha Ojha（IBM工程经理、Ceph执行委员会成员）主持了会议，主题为Ceph社区现状及即将发布的Tentacle版本更新。以下是会议的主要内容：</p><h3 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h3><ul><li><strong>主持人</strong>: Neha Ojha</li><li><strong>会议主题</strong>: Ceph社区现状及Tentacle版本更新</li><li><strong>地点</strong>: 伦敦（Ceph Days活动）</li><li><strong>赞助方</strong>: IBM和Coronicle</li></ul><h3 id="社区现状与统计" tabindex="-1">社区现状与统计 <a class="header-anchor" href="#社区现状与统计" aria-label="Permalink to &quot;社区现状与统计&quot;">​</a></h3><ul><li><strong>贡献者规模</strong>: 约1400名GitHub贡献者</li><li><strong>代码规模</strong>: 70万+行代码，15万次提交</li><li><strong>版本支持策略</strong>: 支持 N-2 版本（当前支持Squid和Reef，未来支持Tentacle）</li></ul><h3 id="项目里程碑与社区活动" tabindex="-1">项目里程碑与社区活动 <a class="header-anchor" href="#项目里程碑与社区活动" aria-label="Permalink to &quot;项目里程碑与社区活动&quot;">​</a></h3><ul><li><strong>SAFLCAN 2023</strong>: 去年活动成功举办，T恤设计获好评</li><li><strong>存储规模</strong>: Ceph集群总容量达1.8艾字节</li><li><strong>社区参与渠道</strong>: Slack频道、Meetup小组、Ceph用户委员会</li><li><strong>学术合作</strong>: 与多所大学合作开发新功能</li><li><strong>性能里程碑</strong>: Squid版本中实现1 TB/s的吞吐量</li></ul><h3 id="ceph基金会更新" tabindex="-1">Ceph基金会更新 <a class="header-anchor" href="#ceph基金会更新" aria-label="Permalink to &quot;Ceph基金会更新&quot;">​</a></h3><ul><li><strong>新成员</strong>: Digital Ocean加入为银牌会员，现有钻石会员包括Bluebug、IBM和45 Drives</li><li><strong>新职位</strong>: Anthony Middleton担任社区经理</li><li><strong>活动计划</strong>: 全球Ceph Days，SAFLCAN 2025将于10月在加拿大温哥华举办</li></ul><h3 id="tentacle版本技术亮点" tabindex="-1">Tentacle版本技术亮点 <a class="header-anchor" href="#tentacle版本技术亮点" aria-label="Permalink to &quot;Tentacle版本技术亮点&quot;">​</a></h3><ul><li><strong>核心改进</strong>: Erasure Coding性能优化，目录列表性能改进，可用性评分，Stretch Cluster支持，网络分裂警报</li><li><strong>Bluestore优化</strong>: 压缩可调性，分配器性能改进</li><li><strong>Crimson（下一代OSD）</strong>: 用户体验改进，功能开发，Seastore后端</li><li><strong>对象存储（RGW）</strong>: S3 API扩展，性能优化，新功能</li><li><strong>块存储（RBD）</strong>: 灾难恢复，在线迁移，内核支持</li><li><strong>文件存储（CephFS）</strong>: 稳定性改进，新特性</li><li><strong>Dashboard与管理工具</strong>: 多集群管理，Cephadm改进</li><li><strong>LUKS加密</strong>: 迁移支持</li><li><strong>遥测与文档</strong>: 遥测数据价值，文档改进</li><li><strong>开发者体验与性能基准</strong>: CI/CD优化，CBT（Ceph Benchmarking Tool）</li></ul><h3 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h3><ul><li>参与社区调查，关注性能与易用性</li><li>试用Tentacle的Tech Preview功能</li><li>关注即将举办的Ceph Days和SAFLCAN 2025</li></ul><p>会议强调了Ceph社区的活跃发展和Tentacle版本的技术亮点，包括性能优化、功能增强和社区参与的增加。</p>',14)])])}const u=t(r,[["render",n]]);export{d as __pageData,u as default};
